package com.foodbridge.orders;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.data.domain.Sort;import java.util.List;
@Controller public class StaffOrderController {private final PurchaseOrderRepository orders;public StaffOrderController(PurchaseOrderRepository orders){this.orders=orders;}@GetMapping("/staff/orders") public String orders(Model model){model.addAttribute("orders",orders.findAll(Sort.by(Sort.Direction.DESC,"createdAt")));model.addAttribute("statuses",List.of(OrderStatus.READY_FOR_PICKUP,OrderStatus.PICKED_UP,OrderStatus.CANCELLED));return "orders/staff";}}
